"""Local creator UI fixture, with isolated in-memory save storage."""
from pathlib import Path
R=Path(__file__).resolve().parents[1]
isolation='''<script>(()=>{const d=new Map(),s={getItem:k=>d.get(k)??null,setItem:(k,v)=>d.set(k,String(v)),removeItem:k=>d.delete(k),clear:()=>d.clear(),key:i=>[...d.keys()][i]??null,get length(){return d.size}};Object.defineProperty(window,'localStorage',{value:s});Object.defineProperty(window,'sessionStorage',{value:s});})();</script>'''
payload='''<section id="creatorQA" style="position:fixed;right:6px;top:6px;z-index:999999;background:#162636;color:white;padding:8px;font:11px system-ui;max-width:300px"><button id="openCreatorQA">Open character creator</button><button id="hideCreatorQA">Hide test panel</button><pre id="creatorQAResult" style="max-height:160px;overflow:auto">Ready</pre></section><script>(()=>{document.getElementById('hideCreatorQA').onclick=()=>document.getElementById('creatorQA').hidden=true;document.getElementById('openCreatorQA').onclick=async()=>{while(!window.__BF3||!window.HERO3D?.ready)await new Promise(r=>setTimeout(r,40));__BF3.loadMode('rl');__BF3.openCharCreate();};setInterval(()=>{if(!window.__creatorWizardState)return;const s=__creatorWizardState(),p=window.__creatorPreviewState;document.getElementById('creatorQAResult').textContent=JSON.stringify({wizard:s,preview:p,faceButton:document.querySelector('#ccFace')?.getAttribute('aria-pressed'),fullButton:document.querySelector('#ccFull')?.getAttribute('aria-pressed')},null,2);},80);})();</script>'''
source=(R/'public/3d/index.html').read_text(encoding='utf8').replace('<head>','<head><base href="/3d/">'+isolation,1).replace('if(m && m[1]!==VERSION3D)','if(false && m && m[1]!==VERSION3D)')
(R/'public/3d/.qa-creator-camera.html').write_text(source.replace('</body>',payload+'</body>'),encoding='utf8')
print('Built local creator camera fixture. Real saves untouched.')
